VALUES ('chu-r0', '绎', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊狂之子，鬻熊后裔，楚国受西周分封后的首任国君。周成王时受封于楚蛮，获子男之田，居丹阳；与鲁、卫、晋、齐诸侯共事成王。具体在位起讫年代失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊绎"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]'::jsonb, NULL, NULL, '熊绎')
