VALUES ('chu-r4', '杨', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊䵣之子、熊胜之弟，继兄为楚君，子熊渠继位。世系见于《史记·楚世家》，名又作熊炀；具体在位年代与政事未见详载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊杨"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]'::jsonb, NULL, NULL, '熊杨')
