INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('chu-r5', '渠', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊杨之子，西周楚君。周夷王时兴兵伐庸、扬越，进至鄂，立三子为句亶王、鄂王和越章王；周厉王时惧周讨伐，撤去王号。具体在位起讫年代失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊渠"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]'::jsonb, NULL, NULL, '熊渠')
