INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('chu-r6', '挚', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊挚红，一作熊挚。《史记·楚世家》记为熊渠之子，曾封鄂王，后继为楚君；关于其继位、去世及与熊延的关系，传世文献有异说。具体在位起讫年代失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊挚红"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]'::jsonb, NULL, NULL, '熊挚红')
