INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('chu-r7', '延', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊勇之父，西周楚君。《史记·楚世家》记其为熊挚红之弟，杀兄代立；关于熊挚与熊延的继承关系，传世文献有异说。即位年代失考，后由子熊勇继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊延"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]'::jsonb, NULL, NULL, '熊延')
