VALUES ('chu-r8', '勇', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊延之子，前847—前838年在位。《史记·楚世家》载其六年周厉王出奔彘，十年卒，弟熊严继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊勇"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]'::jsonb, NULL, NULL, '熊勇')
