VALUES ('chu-r9', '严', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊勇之弟，继兄为楚君，前837—前828年在位。有伯霜、仲雪、叔堪、季徇四子；在位十年而卒，长子伯霜继位，是为熊霜。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊严"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]'::jsonb, NULL, NULL, '熊严')
