VALUES ('chu-r10', '霜', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊严之子。卒后三弟争位，仲雪死、叔堪亡濮，少弟熊徇得立，前827–前822年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊霜"}]'::jsonb, NULL, NULL, '熊霜')
