VALUES ('chu-r11', '徇', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊霜少弟熊徇，平定兄弟之争后继位。在位时郑桓公初封于郑，前821–前800年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊徇"}]'::jsonb, NULL, NULL, '熊徇')
