VALUES ('chu-r12', '咢', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '熊徇之子熊咢，楚国世系所载君主，事迹少见详载，年代见于《楚世家》，前799–前791年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊咢"}]'::jsonb, NULL, NULL, '熊咢')
