VALUES ('chu-r13', '仪', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '芈姓，称若敖。周幽王被杀、平王东迁时在位，为楚国较早有称号之君，前790–前764年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/若敖"}]'::jsonb, NULL, NULL, '若敖')
