VALUES ('chu-r16', '通', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '芈姓，名通。杀侄代位后自立为楚王，开诸侯僭号称王先河；连年征伐，前690年伐随途中病逝，前740–前690年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚武王"}]'::jsonb, '武王', NULL, '楚武王')
