VALUES ('chu-r17', '赀', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '武王之子，迁都郢，灭申、邓等国，楚国始成南方大国。前675年卒，前689–前675年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚文王"}]'::jsonb, '文王', NULL, '楚文王')
