VALUES ('chu-r18', '艰', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '文王之子熊艰，称堵敖。欲杀弟熊恽未就，五年后熊恽与随国袭杀之而自立，前674–前672年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/堵敖"}]'::jsonb, NULL, NULL, '堵敖')
