VALUES ('chu-r19', '恽', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '杀兄堵敖即位，曾与晋、齐争霸。前626年被太子商臣围困，自知不免而死，前671–前626年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚成王"}]'::jsonb, '成王', NULL, '楚成王')
