VALUES ('chu-r20', '商臣', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '成王太子熊商臣，弑父自立，谥穆王。任用子重等，与晋争夺郑国，前625–前614年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚穆王"}]'::jsonb, '穆王', NULL, '楚穆王')
