VALUES ('xiong-zhuang', '侣', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '穆王之子。初期韬光养晦，后励精图治；邲之战大败晋军，又曾问鼎洛邑，列春秋五霸，前613–前591年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚庄王"}]'::jsonb, '庄王', NULL, '楚庄王')
