VALUES ('chu-r23', '招', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '共王之子，国事多赖令尹子囊。在位十四年，楚国与诸侯关系趋于守成，前559–前545年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚康王"}]'::jsonb, '康王', NULL, '楚康王')
