VALUES ('chu-r24', '员', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '康王之子熊员，称郏敖。在位仅三年，叔父熊围弑之自立，是为灵王，前544–前541年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郏敖"}]'::jsonb, NULL, NULL, '郏敖')
