VALUES ('chu-r25', '围', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '康王弟，弑侄郏敖即位。大修章华台、征伐诸侯；前529年弟比、子弃疾谋反，灵王自杀，前540–前529年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚灵王"}]'::jsonb, '灵王', NULL, '楚灵王')
