VALUES ('chu-r26', '比', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '共王之子熊比，灵王弟。趁兄自杀自立，仅十余日后即被弃疾逼迫自杀，前529年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/比"}]'::jsonb, NULL, NULL, '比')
