VALUES ('chu-r27', '居', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '弃疾改名熊居即位，诛兄比。诬陷伍奢、杀伍子胥父兄，伍子胥逃亡吴国，前528–前516年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚平王"}]'::jsonb, '平王', NULL, '楚平王')
