VALUES ('chu-r28', '珍', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '平王之子。伍子胥引吴军入郢，昭王出走；后复国，与陈、蔡联军败吴于颍水，前515–前489年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚昭王"}]'::jsonb, '昭王', NULL, '楚昭王')
