VALUES ('chu-r30', '中', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '惠王之子熊中，谥简王。在位时屡伐郑、卫等国，前408年卒，前431–前408年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚简王"}]'::jsonb, '简王', NULL, '楚简王')
