VALUES ('chu-r31', '当', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '简王之子熊当，谥声王。在位五年而卒，战国初期楚国仍列大国，前407–前402年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚声王"}]'::jsonb, '声王', NULL, '楚声王')
