VALUES ('chu-r32', '疑', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '声王之子，用吴起变法，明审法令、裁汰冗官、开疆拓土。变法未久而卒，前401–前381年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚悼王"}]'::jsonb, '悼王', NULL, '楚悼王')
