VALUES ('chu-r33', '臧', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '悼王之子熊臧，在位十一年，国政继吴起变法之后渐趋稳定，前380–前370年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚肃王"}]'::jsonb, '肃王', NULL, '楚肃王')
