VALUES ('chu-r34', '良夫', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '肃王弟。在位时楚为南方强国，曾与齐宣王、秦惠文王并列称雄，前369–前340年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚宣王"}]'::jsonb, '宣王', NULL, '楚宣王')
