VALUES ('chu-r35', '商', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '宣王之子熊商，谥威王。破越、灭中山，威震江淮，前329年卒，前339–前329年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚威王"}]'::jsonb, '威王', NULL, '楚威王')
