VALUES ('chu-r36', '槐', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '威王之子。初期用昭雎，后受张仪欺诈背齐；接见秦王于武关，客死于秦，前328–前299年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚怀王"}]'::jsonb, '怀王', NULL, '楚怀王')
