VALUES ('chu-r37', '横', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '怀王之子，秦伐楚取汉中。白起反攻，前279年鄢郢失陷，楚国迁都陈，前298–前263年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚顷襄王"}]'::jsonb, '顷襄王', NULL, '楚顷襄王')
