VALUES ('chu-r38', '元', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '顷襄王之子，迁都淮南寿春。封春申君黄歇为令尹，相楚二十余年，前262–前238年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚考烈王"}]'::jsonb, '考烈王', NULL, '楚考烈王')
