VALUES ('chu-r39', '悍', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '考烈王之子熊悍，谥幽王。在位时楚国国力日衰，战国末期已难抗秦，前237–前228年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚幽王"}]'::jsonb, '幽王', NULL, '楚幽王')
