VALUES ('chu-r40', '犹', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '考烈王少子熊犹，谥哀王，幽王弟。幽王死后继立，仅数月即被兄负刍所杀，前228年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚哀王"}]'::jsonb, '哀王', NULL, '楚哀王')
