VALUES ('chu-r41', '负刍', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '考烈王庶子，杀哀王自立。秦将王翦破楚，负刍被俘，楚国灭亡，前227–前223年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/负刍"}]'::jsonb, NULL, NULL, '负刍')
