VALUES ('chu-r42', '启', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '考烈王庶子熊启，曾任秦相。秦末项燕立为楚王，与秦军战于淮南而败死，前223年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/昌平君"}]'::jsonb, NULL, NULL, '昌平君')
