VALUES ('chu-r43', '熊心', 'chu-chunqiu', ARRAY[]::text[], '芈', '熊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '楚怀王之后熊心，项羽所立义帝。后徙郴县，被项羽遣人所弑，前208–前205年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/义帝"}]'::jsonb, NULL, NULL, '义帝')
