VALUES ('qu-yuan', '屈原', 'chu-chunqiu', ARRAY[]::text[], NULL, NULL, -340, 1, NULL, 'year', -278, 1, NULL, 'year', ARRAY['诗人','政治家'], '战国楚国诗人、政治人物，曾任左徒，主张举贤任能并联齐抗秦，后遭疏远。秦军攻破楚都郢后，他作《怀沙》并投汨罗江；《离骚》《九歌》等作品传世。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/屈原"}]'::jsonb, NULL, NULL, NULL)
