VALUES ('lao-zi', '老子', 'chu-chunqiu', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['思想家'], '春秋末思想家，道家学派重要代表，传统上尊称老子，姓李名耳。相传曾任周守藏室之史，后西出函谷关；《道德经》托名于他，成书与生平年代仍有争议。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/老子"}]'::jsonb, NULL, NULL, NULL)
